create schema private_reviewed_existing_history;
revoke all on schema private_reviewed_existing_history from public,anon,authenticated,service_role;
create function private_reviewed_existing_history.historical_entry_season(document jsonb,entry jsonb) returns text language sql immutable set search_path=pg_catalog,public,private_dfb_release as $$
 select case when document->>'id'='gb-npl-midlands-historical-unavailable-2026-10-23-v1' and document->>'provider'='isthmian' and document->>'competitionSlug'='gb-npl-midlands' and document->>'sourceLeagueCode'='npl/67d7c7bb74247876e6dae40c/2026-27' and entry->>'sourceMatchId'='6896abc31c6f4c56212c7ac5' and entry->>'season'='2025/26' then '2025/26' else private_dfb_release.historical_entry_season_v4(document,entry) end
$$;
revoke all on function private_reviewed_existing_history.historical_entry_season(jsonb,jsonb) from public,anon,authenticated,service_role;

-- Extend the central installer only for these immutable, exact reviewed tuples.
do $$declare d text;changed text;begin
 select pg_get_functiondef('public.apply_historical_statistics_policy(bigint,text,text,jsonb)'::regprocedure) into d;
 changed:=replace(d,$n$when 'mlsz'then 'HU'end$n$,$n$when 'mlsz'then 'HU'when 'isthmian'then 'GB'when 'hlf'then 'RO'when 'nfsbih'then 'BA'end$n$);
 if changed=d and position($n$when 'isthmian'then 'GB'when 'hlf'then 'RO'when 'nfsbih'then 'BA'end$n$ in d)=0 then raise exception 'REVIEWED_EXISTING: country mapping drift';end if;
 if position('reviewed-existing fixed tuple required' in d)=0 then
 changed:=replace(changed,$n$if c.id is null or p.id is null or c.active or c.slug is distinct from p.document->>'competitionSlug' or c.source is distinct from p.document->>'provider'$n$,$n$if p.document->>'sourcePolicy'='reviewed-existing-history-20261023-v1' and not ((c.id=979 and c.slug='gb-npl-midlands' and c.source='isthmian' and c.source_league_code='npl/67d7c7bb74247876e6dae40c/2026-27' and p.id='gb-npl-midlands-historical-unavailable-2026-10-23-v1' and p.policy_sha256='5f88bd981434a2d1bb8097a71d4b62974601b0eb01758509b345c8eb6b0c6924') or (c.id=984 and c.slug='gb-sfl-d1-south' and c.source='isthmian' and c.source_league_code='sfl/69d0bdf9b616bafb97331d41/2026-27' and p.id='gb-sfl-d1-south-historical-unavailable-2026-10-23-v1' and p.policy_sha256='682dbaa0e1acfb0a4a03da9da93cdc706eb0d16dc4a8df180e994f6980369a30') or (c.id=497 and c.slug='ro-liga3-s1' and c.source='hlf' and c.source_league_code='national/fotbal/2026-2027/superscore-liga-3/sezon-regular/serie-1' and p.id='ro-liga3-s1-historical-unavailable-2026-10-23-v1' and p.policy_sha256='b6686671855dfa9a6f96fa8cf67d530aa4fc4208f859e783929cb36140169329') or (c.id=998 and c.slug='ba-wwin-liga-bih' and c.source='nfsbih' and c.source_league_code='wwin-liga-bih/54152223' and p.id='ba-wwin-liga-bih-historical-unavailable-2026-10-23-v1' and p.policy_sha256='fa48230a81834fe5d182012bdf34ab5df513392f5000ad4e0186f24d5b9a1366')) then raise exception 'HISTORICAL_POLICY: reviewed-existing fixed tuple required';end if;
 if c.id is null or p.id is null or c.active or c.slug is distinct from p.document->>'competitionSlug' or c.source is distinct from p.document->>'provider'$n$);
  if changed=d then raise exception 'REVIEWED_EXISTING: installer tuple guard drift';end if;
 end if;
 if changed<>d then execute changed;end if;
 select pg_get_functiondef('public.upsert_unavailable_historical_match(bigint,text,text,text,text,jsonb)'::regprocedure) into d;
 if position('reviewed-existing fixed report required' in d)=0 then
 changed:=replace(d,$n$if e is null or p_raw_sha256 is distinct from e->>'rawSha256' then raise exception 'HISTORICAL_POLICY: unapproved match or raw hash';end if;$n$,$n$if e is null or p_raw_sha256 is distinct from e->>'rawSha256' then raise exception 'HISTORICAL_POLICY: unapproved match or raw hash';end if;
 if p.document->>'sourcePolicy'='reviewed-existing-history-20261023-v1' and not ((c.id=979 and c.source='isthmian' and p.policy_sha256='5f88bd981434a2d1bb8097a71d4b62974601b0eb01758509b345c8eb6b0c6924' and p_source_match_id in('6a590670ce9ef452b61f386d','6896abc31c6f4c56212c7ac5')) or (c.id=984 and c.source='isthmian' and p.policy_sha256='682dbaa0e1acfb0a4a03da9da93cdc706eb0d16dc4a8df180e994f6980369a30' and p_source_match_id='6a5a1b79ce9ef452b61f4398') or (c.id=497 and c.source='hlf' and p.policy_sha256='b6686671855dfa9a6f96fa8cf67d530aa4fc4208f859e783929cb36140169329' and p_source_match_id='f43d55c1-6530-49dc-a02e-4d7e578d6205') or (c.id=998 and c.source='nfsbih' and p.policy_sha256='fa48230a81834fe5d182012bdf34ab5df513392f5000ad4e0186f24d5b9a1366' and p_source_match_id in('54152295','54152303'))) then raise exception 'HISTORICAL_POLICY: reviewed-existing fixed report required';end if;$n$);
 changed:=replace(changed,$n$when 'fcf' then 'es'||p_source_match_id else null end$n$,$n$when 'fcf' then 'es'||p_source_match_id when 'isthmian' then case when (c.id=979 and p_source_match_id in('6a590670ce9ef452b61f386d','6896abc31c6f4c56212c7ac5')) or (c.id=984 and p_source_match_id='6a5a1b79ce9ef452b61f4398') then 'gb'||p_source_match_id end when 'hlf' then case when c.id=497 and p_source_match_id='f43d55c1-6530-49dc-a02e-4d7e578d6205' then p_source_match_id end when 'nfsbih' then case when c.id=998 and p_source_match_id in('54152295','54152303') then 'ba'||p_source_match_id end else null end$n$);
 changed:=replace(changed,$n$private_dfb_release.historical_entry_season_v4(p.document,e)$n$,$n$private_reviewed_existing_history.historical_entry_season(p.document,e)$n$);
