 ('ro-liga3-s1',497::bigint,'f43d55c1-6530-49dc-a02e-4d7e578d6205','f43d55c1-6530-49dc-a02e-4d7e578d6205',133334::bigint,10663::bigint,'2026/27',1,3016::bigint,3017::bigint,'2026-08-29'::date,2,1,33,3,null::text,null::int),
 ('ba-wwin-liga-bih',998::bigint,'54152295','ba54152295',576391::bigint,35409::bigint,'2026/27',5,10876::bigint,10872::bigint,'2026-09-02'::date,1,2,32,3,null::text,null::int),
 ('ba-wwin-liga-bih',998::bigint,'54152303','ba54152303',576399::bigint,35410::bigint,'2026/27',6,10874::bigint,10876::bigint,'2026-09-06'::date,2,1,32,3,null::text,null::int)
 ) as v(slug,cid,source_match_id,report_id,mid,rid,season,rno,home_id,away_id,played_on,home_goals,away_goals,appearances,goals,source_phase,source_round)
 where v.slug=p_slug
$$;

create function private_reviewed_existing_history.capture(p_slug text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;x jsonb;begin select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 select jsonb_build_object(
  'competition',(select to_jsonb(c) from competitions c where c.id=t.cid),
  'rounds',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]') from rounds r where r.competition_id=t.cid),
  'matches',(select coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]') from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid),
  'players',(select coalesce(jsonb_agg(to_jsonb(p) order by p.id),'[]') from players p where p.competition_id=t.cid),
  'teams',(select coalesce(jsonb_agg(to_jsonb(te) order by te.id),'[]') from teams te where te.id in(select m.home_team_id from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid union select m.away_team_id from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid)),
  'appearances',(select coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]') from appearances a where a.match_id in(select rt.mid from private_reviewed_existing_history.report_targets(t.slug)rt)),
  'goals',(select coalesce(jsonb_agg(to_jsonb(g) order by g.id),'[]') from goals g where g.match_id in(select rt.mid from private_reviewed_existing_history.report_targets(t.slug)rt)),
  'otherAppearances',(select coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]') from appearances a join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where r.competition_id=t.cid and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)rt where rt.mid=m.id)),
  'otherGoals',(select coalesce(jsonb_agg(to_jsonb(g) order by g.id),'[]') from goals g join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=t.cid and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)rt where rt.mid=m.id)),
  'playerScores',(select coalesce(jsonb_agg(to_jsonb(ps) order by ps.round_id,ps.player_id),'[]') from player_scores ps where ps.round_id in(select distinct rt.rid from private_reviewed_existing_history.report_targets(t.slug)rt)),
  'roundScores',(select coalesce(jsonb_agg(to_jsonb(ts) order by ts.round_id,ts.fantasy_team_id),'[]') from tocke_krogov ts where ts.round_id in(select distinct rt.rid from private_reviewed_existing_history.report_targets(t.slug)rt)),
  'seasonStats',(select coalesce(jsonb_agg(to_jsonb(ss) order by ss.player_id,ss.season),'[]') from statistika_igralcev ss join players p on p.id=ss.player_id where p.competition_id=t.cid)
 ) into x;return x;end$$;

create function private_reviewed_existing_history.opening(p_slug text,p_clock timestamptz) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;r rounds%rowtype;day date;n int;local_day date;begin select * into t from private_reviewed_existing_history.target(p_slug);local_day:=(p_clock at time zone 'Europe/Ljubljana')::date;
 select * into r from rounds where competition_id=t.cid and season='2026/27' and deadline_at>p_clock order by number limit 1;
 perform private_reviewed_existing_history.require(r.id is not null and r.lineups_locked_at is null,'no future unlocked first round');
 select min(played_on),count(*) into day,n from matches where round_id=r.id;
 perform private_reviewed_existing_history.require(n>0 and day>=local_day and not exists(select 1 from matches where round_id=r.id and(played_on is null or played_on<local_day or imported_at is not null or zapisnik_id is not null or home_goals<>0 or away_goals<>0 or statistics_status<>'available' or kontumacija or vir_brez_izida)) and not exists(select 1 from appearances a join matches m on m.id=a.match_id where m.round_id=r.id) and not exists(select 1 from goals g join matches m on m.id=g.match_id where m.round_id=r.id) and not exists(select 1 from fantasy_lineups where round_id=r.id),'first future round must remain future, unlocked and empty');
 return jsonb_build_object('roundId',r.id,'round',r.number,'firstPlayedOn',day,'deadline',r.deadline_at);
end$$;

create function private_reviewed_existing_history.state_sha(p_slug text) returns text language plpgsql stable security definer set search_path=public,pg_temp as $$
declare t record;begin select * into t from private_reviewed_existing_history.target(p_slug);return encode(sha256(convert_to(jsonb_build_object(
 'competition',(select to_jsonb(c)-'active' from competitions c where c.id=t.cid),
 'players',(select coalesce(jsonb_agg((to_jsonb(p)-'value'-'value_start'-'repriced_at'-'repriced_week'-'value_locked'-'position'-'position_source') order by p.id),'[]') from players p where p.competition_id=t.cid),
 'rounds',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]') from rounds r where r.competition_id=t.cid),
 'matches',(select coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]') from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid),
 'appearances',(select coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]') from appearances a join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where r.competition_id=t.cid),
 'goals',(select coalesce(jsonb_agg(to_jsonb(g) order by g.id),'[]') from goals g join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=t.cid)
 )::text,'UTF8')),'hex');end$$;
create function private_reviewed_existing_history.price_sha(p_slug text) returns text language plpgsql stable security definer set search_path=public,pg_temp as $$declare t record;begin select * into t from private_reviewed_existing_history.target(p_slug);return encode(sha256(convert_to(coalesce((select jsonb_agg(jsonb_build_array(id,active,value,value_start,value_locked,position,position_source,repriced_week,repriced_at) order by id)::text from players where competition_id=t.cid),'[]'),'UTF8')),'hex');end$$;

create function private_reviewed_existing_history.check_targets(p_slug text,p_main_sha text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;c competitions%rowtype;p private_historical_statistics.policies%rowtype;m matches%rowtype;target_row record;e jsonb;first jsonb;before_image jsonb;side record;target_count int;entry_count int;source_country text;
begin
 select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 perform private_reviewed_existing_history.require(current_setting('transaction_isolation')='read committed' and p_main_sha~'^[a-f0-9]{40}$','READ COMMITTED and exact main SHA required');
 lock table countries,competitions,rounds,teams,players,matches,appearances,goals,fantasy_teams,fantasy_roster,fantasy_lineups,fantasy_transfers,fantasy_chips,position_votes,position_votes_deleted,assist_votes,assist_votes_deleted,player_scores,statistika_igralcev,tocke_krogov,uradne_odsotnosti,profil_igralca_plus in share row exclusive mode;
 lock table private_historical_statistics.policies,private_historical_statistics.installed_policies,private_historical_statistics.markers,private_historical_statistics.source_club_bindings,private_reviewed_existing_history.cleanup_receipts,private_reviewed_existing_history.price_receipts in share row exclusive mode;
 select * into c from competitions where id=t.cid for update;select * into p from private_historical_statistics.policies where id=t.policy_id;
 source_country:=case t.provider when 'isthmian' then 'GB' when 'hlf' then 'RO' when 'nfsbih' then 'BA' end;
 perform private_reviewed_existing_history.require(c.slug=t.slug and c.source=t.provider and c.source_league_code=t.code and c.source_policy is null and not c.sezona_koledarska and not c.active and p.policy_sha256=t.policy_sha and p.document->>'competitionSlug'=t.slug and p.document->>'provider'=t.provider and p.document->>'sourcePolicy'='reviewed-existing-history-20261023-v1' and exists(select 1 from countries where id=c.country_id and code=source_country),'exact inactive country/source/code/catalog tuple required');
 perform private_reviewed_existing_history.require(not exists(select 1 from fantasy_teams where competition_id=t.cid) and not exists(select 1 from fantasy_roster fr join players pp on pp.id=fr.player_id where pp.competition_id=t.cid) and not exists(select 1 from fantasy_lineups l join rounds rr on rr.id=l.round_id where rr.competition_id=t.cid) and not exists(select 1 from fantasy_transfers ft join rounds rr on rr.id=ft.round_id where rr.competition_id=t.cid) and not exists(select 1 from fantasy_chips fc join rounds rr on rr.id=fc.round_id where rr.competition_id=t.cid),'no user-owned teams/rosters/lineups/transfers/chips required');
 perform private_reviewed_existing_history.require(not exists(select 1 from position_votes v join players pp on pp.id=v.player_id where pp.competition_id=t.cid) and not exists(select 1 from position_votes_deleted v join players pp on pp.id=v.player_id where pp.competition_id=t.cid),'no user position-vote activity required');
 select count(*) into target_count from private_reviewed_existing_history.report_targets(t.slug);select count(*) into entry_count from jsonb_array_elements(p.document->'entries');
 perform private_reviewed_existing_history.require(target_count=entry_count and target_count>0 and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)candidate where not exists(select 1 from jsonb_array_elements(p.document->'entries')as ent(value) where ent.value->>'sourceMatchId'=candidate.source_match_id)),'policy entries must equal the six exact reviewed report tuples');
 for target_row in select * from private_reviewed_existing_history.report_targets(t.slug) order by mid loop
  select value into e from jsonb_array_elements(p.document->'entries') where value->>'sourceMatchId'=target_row.source_match_id;
  select * into m from matches where id=target_row.mid and round_id=target_row.rid and home_team_id=target_row.home_id and away_team_id=target_row.away_id for update;
  perform private_reviewed_existing_history.require(m.id=target_row.mid and m.played_on=target_row.played_on and m.home_goals=target_row.home_goals and m.away_goals=target_row.away_goals and m.zapisnik_id=target_row.report_id and m.source_url=e->>'sourceUrl' and m.imported_at is not null and m.statistics_status='available' and m.statistics_reason is null and not m.kontumacija and not m.vir_brez_izida and m.source_phase is null and m.source_round is null and (select count(*) from appearances where match_id=target_row.mid)=target_row.appearances and (select count(*) from goals where match_id=target_row.mid)=target_row.goals,'exact approved existing report header and individual row counts required');
  perform private_reviewed_existing_history.require(exists(select 1 from rounds where id=target_row.rid and competition_id=t.cid and number=target_row.rno and season=target_row.season),'exact reviewed native target round required');
  perform private_reviewed_existing_history.require(not exists(select 1 from goals g where g.match_id=target_row.mid and (g.team_id not in(target_row.home_id,target_row.away_id) or not exists(select 1 from appearances a where a.match_id=g.match_id and a.player_id=g.scorer_id and a.team_id=g.team_id))),'no foreign scorer/team relation on exact cleanup target');
  perform private_reviewed_existing_history.require(not exists(select 1 from assist_votes av join goals g on g.id=av.goal_id where g.match_id=target_row.mid) and not exists(select 1 from assist_votes_deleted av join goals g on g.id=av.goal_id where g.match_id=target_row.mid) and not exists(select 1 from goals g where g.match_id=target_row.mid and (g.assist_player_id is not null or g.assist_confirmed_at is not null or g.assist_none_confirmed_at is not null)),'no user-confirmed assist activity may be cascaded by exact goal cleanup');
  for side in select e->>'homeSourceClubId' club,target_row.home_id tid union all select e->>'awaySourceClubId',target_row.away_id loop
   perform private_reviewed_existing_history.require(exists(select 1 from private_historical_statistics.source_club_bindings b join teams x on x.id=side.tid join countries cc on cc.id=x.country_id where b.provider=t.provider and b.source_club_id=side.club and b.source_category_id='' and b.country_code=source_country and ((b.bound_team_id=side.tid) or (b.bound_team_id is null and x.name=any(b.canonical_names) and (select count(*) from teams tx where tx.country_id=x.country_id and tx.name=any(b.canonical_names))=1)) and cc.code=b.country_code),'exact reviewed source/native club binding required');
  end loop;
 end loop;
 perform private_reviewed_existing_history.require(not exists(select 1 from pg_constraint fk join pg_class child on child.oid=fk.conrelid join pg_class parent on parent.oid=fk.confrelid where fk.contype='f' and fk.confrelid in('public.appearances'::regclass,'public.goals'::regclass,'public.player_scores'::regclass,'public.statistika_igralcev'::regclass,'public.tocke_krogov'::regclass) and not(child.relname='assist_votes' and parent.relname='goals' and pg_get_constraintdef(fk.oid)='FOREIGN KEY (goal_id) REFERENCES goals(id) ON DELETE CASCADE')) and not exists(select 1 from pg_attribute a join pg_class rel on rel.oid=a.attrelid join pg_namespace ns on ns.oid=rel.relnamespace where ns.nspname in('public','scout') and rel.relkind in('r','p') and a.attnum>0 and not a.attisdropped and a.attname in('appearance_id','goal_id') and not(ns.nspname='public' and rel.relname in('assist_votes','assist_votes_deleted') and a.attname='goal_id')),'unexpected foreign-key or individual-row reference could be deleted');
 first:=private_reviewed_existing_history.opening(t.slug,clock_timestamp());
 perform private_reviewed_existing_history.require((select count(*) from matches mm join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid and rr.season='2026/27' and mm.imported_at is not null)=t.current_reports and not exists(select 1 from matches mm join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid and rr.season='2026/27' and mm.imported_at is not null and (mm.statistics_status<>'available' or mm.home_goals is null or mm.away_goals is null or mm.zapisnik_id is null)),'current imported-report count must match the reviewed inventory');
 perform private_reviewed_existing_history.require(t.cid<>979 or (select count(*) from matches mm join rounds rr on rr.id=mm.round_id where rr.competition_id=979 and rr.season='2025/26' and mm.imported_at is not null and mm.statistics_status='available')=t.archive_reports,'NPL 2025/26 archive must retain all 462 approved imported reports');
 perform private_reviewed_existing_history.require(not exists(select 1 from matches mm join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid and coalesce(mm.played_on,rr.played_on)<(clock_timestamp() at time zone 'Europe/Ljubljana')::date and not mm.kontumacija and mm.vir_brez_izida is not true and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)rt where target_row.mid=mm.id) and (mm.imported_at is null or mm.statistics_status not in('available','unavailable_historical'))),'every past current or historical fixture must be imported or explicitly covered');
 perform private_reviewed_existing_history.require(not exists(select 1 from private_historical_statistics.markers mk where mk.competition_id=t.cid),'no pre-existing historical marker allowed');
 before_image:=private_reviewed_existing_history.capture(t.slug);
 return jsonb_build_object('target',to_jsonb(t),'opening',first,'beforeImage',before_image,'beforeImageText',before_image::text,'beforeSha256',encode(sha256(convert_to(before_image::text,'UTF8')),'hex'));
end$$;

create function public.prepare_reviewed_existing_cleanup(p_slug text,p_main_sha text,p_policy_sha text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare d jsonb;t record;p private_historical_statistics.policies%rowtype;ids jsonb;begin
 select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 perform private_reviewed_existing_history.require(p_policy_sha=t.policy_sha,'exact canonical policy SHA required');
 select * into p from private_historical_statistics.policies where id=t.policy_id;
 perform private_reviewed_existing_history.require(p.policy_sha256=t.policy_sha and p.document->>'competitionSlug'=t.slug,'immutable reviewed policy row required');
 d:=private_reviewed_existing_history.check_targets(p_slug,p_main_sha);
 select jsonb_agg(mid order by mid) into ids from private_reviewed_existing_history.report_targets(t.slug);
 return jsonb_build_object('slug',t.slug,'competitionId',t.cid,'policyId',t.policy_id,'policySha256',t.policy_sha,'beforeImage',d->'beforeImage','beforeImageText',d->>'beforeImageText','beforeSha256',d->>'beforeSha256','firstFantasyPlayedOn',d#>>'{opening,firstPlayedOn}','firstRound',(d#>>'{opening,round}')::int,'firstDeadline',d->'opening'->'deadline','targetMatchIds',ids);
end$$;

create function public.apply_reviewed_existing_cleanup(p_slug text,p_main_sha text,p_policy_sha text,p_before_sha text,p_before_image_text text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;d jsonb;n int;removed_a int:=0;removed_g int:=0;preserved jsonb;before_image jsonb;result jsonb;first jsonb;e jsonb;target_row record;p private_historical_statistics.policies%rowtype;target_ids jsonb;begin
 select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 perform private_reviewed_existing_history.require(not exists(select 1 from private_reviewed_existing_history.cleanup_receipts where slug=t.slug),'cleanup receipt exists; inspect it, never retry');
 perform private_reviewed_existing_history.require(p_policy_sha=t.policy_sha and p_before_sha~'^[a-f0-9]{64}$','exact policy and before-image SHA required');
 d:=private_reviewed_existing_history.check_targets(p_slug,p_main_sha);before_image:=d->'beforeImage';
 perform private_reviewed_existing_history.require(d->>'beforeSha256'=p_before_sha and d->>'beforeImageText'=p_before_image_text,'before image changed or not byte-identical');
 select * into p from private_historical_statistics.policies where id=t.policy_id;first:=d->'opening';
 select jsonb_agg(mid order by mid) into target_ids from private_reviewed_existing_history.report_targets(t.slug);
 update competitions set source_policy='reviewed-existing-history-20261023-v1',prvi_fantasy_krog=(first->>'round')::int where id=t.cid and not active;
 perform public.apply_historical_statistics_policy(t.cid,t.policy_id,t.policy_sha,p.document->'entries');
 for target_row in select * from private_reviewed_existing_history.report_targets(t.slug) order by mid loop
  select value into e from jsonb_array_elements(p.document->'entries') where value->>'sourceMatchId'=target_row.source_match_id;
  delete from goals where match_id=target_row.mid;get diagnostics n=row_count;removed_g:=removed_g+n;perform private_reviewed_existing_history.require(n=target_row.goals,'approved goal row count changed');
  delete from appearances where match_id=target_row.mid;get diagnostics n=row_count;removed_a:=removed_a+n;perform private_reviewed_existing_history.require(n=target_row.appearances,'approved appearance row count changed');
  update matches set imported_at=null where id=target_row.mid and imported_at is not null;perform private_reviewed_existing_history.require(found,'target report no longer imported');
  perform public.upsert_unavailable_historical_match(t.cid,e->>'sourceMatchId',t.policy_id,t.policy_sha,e->>'rawSha256',jsonb_build_object('roundId',target_row.rid,'homeTeamId',target_row.home_id,'awayTeamId',target_row.away_id,'fixture',(e-array['rawSha256','reasonCode'])||jsonb_build_object('season',private_reviewed_existing_history.historical_entry_season(p.document,e))));
 end loop;
 for target_row in select distinct rid from private_reviewed_existing_history.report_targets(t.slug) order by rid loop perform public.recompute_round_scores(target_row.rid);end loop;
 perform public.osvezi_statistiko_igralcev(array(select id from players where competition_id=t.cid));
 perform public.osvezi_tocke_krogov(array(select distinct rid from private_reviewed_existing_history.report_targets(t.slug) order by rid));
 perform public.get_installed_historical_statistics_markers(t.cid);
 preserved:=private_reviewed_existing_history.capture(t.slug);
 perform private_reviewed_existing_history.require(preserved->'otherAppearances'=before_image->'otherAppearances' and preserved->'otherGoals'=before_image->'otherGoals' and preserved->'players'=before_image->'players' and preserved->'teams'=before_image->'teams' and preserved->'rounds'=before_image->'rounds','unrelated football rows changed during cleanup');
 perform private_reviewed_existing_history.require(
  (select coalesce(jsonb_agg(old order by (old->>'id')::bigint),'[]') from jsonb_array_elements(before_image->'matches')old where not exists(select 1 from jsonb_array_elements_text(target_ids)id where id.value=(old->>'id')))
  is not distinct from
  (select coalesce(jsonb_agg(new order by (new->>'id')::bigint),'[]') from jsonb_array_elements(preserved->'matches')new where not exists(select 1 from jsonb_array_elements_text(target_ids)id where id.value=(new->>'id'))),
  'unrelated match collection changed during cleanup');
 result:=jsonb_build_object('slug',t.slug,'mainCommit',p_main_sha,'beforeSha256',p_before_sha,'removedAppearances',removed_a,'removedGoals',removed_g,'unavailableMatches',jsonb_array_length(target_ids),'targetMatchIds',target_ids,'afterSha256',private_reviewed_existing_history.state_sha(t.slug));
 insert into private_reviewed_existing_history.cleanup_receipts(slug,main_sha,policy_sha,before_sha,before_image_text,after_sha,result)values(t.slug,p_main_sha,t.policy_sha,p_before_sha,p_before_image_text,result->>'afterSha256',result);
 return result;
end$$;

create function public.get_reviewed_existing_cleanup_receipt(p_slug text) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare t record;begin select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 return jsonb_build_object('cleanup',(select jsonb_build_object('policySha256',r.policy_sha,'recordedAt',r.recorded_at)||r.result from private_reviewed_existing_history.cleanup_receipts r where r.slug=t.slug),'priceClaim',(select jsonb_build_object('slug',a.slug,'mainCommit',a.main_sha,'policySha256',a.policy_sha,'cleanupBeforeSha256',a.cleanup_before_sha,'footballStateSha256',a.football_state_sha,'claimedAt',a.started_at) from private_reviewed_existing_history.price_attempts a where a.slug=t.slug),'prices',(select jsonb_build_object('slug',p.slug,'mainCommit',p.main_sha,'policySha256',p.policy_sha,'cleanupBeforeSha256',p.cleanup_before_sha,'footballStateSha256',p.football_state_sha,'priceSha256',p.price_vector_sha,'recordedAt',p.recorded_at) from private_reviewed_existing_history.price_receipts p where p.slug=t.slug),'competitions',(select jsonb_build_array(jsonb_build_object('id',c.id,'slug',c.slug,'active',c.active,'markers',public.get_installed_historical_statistics_markers(c.id))) from competitions c where c.id=t.cid));end$$;

create function public.begin_reviewed_existing_prices(p_slug text,p_main_sha text,p_policy_sha text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;c competitions%rowtype;r private_reviewed_existing_history.cleanup_receipts%rowtype;marker jsonb;state text;attempt jsonb;begin
 select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 perform private_reviewed_existing_history.require(current_setting('transaction_isolation')='read committed' and p_main_sha~'^[a-f0-9]{40}$' and p_policy_sha=t.policy_sha,'READ COMMITTED and exact main/policy SHA required');
 lock table competitions,rounds,teams,players,matches,appearances,goals,fantasy_teams,fantasy_roster,fantasy_lineups,fantasy_transfers,fantasy_chips,position_votes,position_votes_deleted,assist_votes,assist_votes_deleted in share row exclusive mode;
 lock table private_historical_statistics.installed_policies,private_historical_statistics.markers,private_reviewed_existing_history.cleanup_receipts,private_reviewed_existing_history.price_attempts,private_reviewed_existing_history.price_receipts in share row exclusive mode;
 select * into c from competitions where id=t.cid for update;select * into r from private_reviewed_existing_history.cleanup_receipts where slug=t.slug;
 perform private_reviewed_existing_history.require(r.main_sha=p_main_sha and r.policy_sha=t.policy_sha and c.active is false and c.slug=t.slug and c.source=t.provider and c.source_league_code=t.code and c.source_policy='reviewed-existing-history-20261023-v1' and not exists(select 1 from fantasy_teams where competition_id=t.cid) and not exists(select 1 from fantasy_roster fr join players pp on pp.id=fr.player_id where pp.competition_id=t.cid) and not exists(select 1 from fantasy_lineups l join rounds rr on rr.id=l.round_id where rr.competition_id=t.cid) and not exists(select 1 from fantasy_transfers ft join rounds rr on rr.id=ft.round_id where rr.competition_id=t.cid) and not exists(select 1 from fantasy_chips fc join rounds rr on rr.id=fc.round_id where rr.competition_id=t.cid) and not exists(select 1 from position_votes v join players pp on pp.id=v.player_id where pp.competition_id=t.cid) and not exists(select 1 from position_votes_deleted v join players pp on pp.id=v.player_id where pp.competition_id=t.cid) and not exists(select 1 from assist_votes av join goals g on g.id=av.goal_id join matches mm on mm.id=g.match_id join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid) and not exists(select 1 from assist_votes_deleted av join goals g on g.id=av.goal_id join matches mm on mm.id=g.match_id join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid),'exact inactive post-cleanup no-activity state required');
 perform private_reviewed_existing_history.require(r.after_sha=private_reviewed_existing_history.state_sha(t.slug) and not exists(select 1 from private_reviewed_existing_history.price_attempts where slug=t.slug) and not exists(select 1 from private_reviewed_existing_history.price_receipts where slug=t.slug),'same post-cleanup state and unused one-time pricing claim required');
 marker:=public.get_installed_historical_statistics_markers(t.cid);perform private_reviewed_existing_history.require(marker->>'policyId'=t.policy_id and marker->>'policySha256'=t.policy_sha and jsonb_array_length(marker->'markers')=(select count(*) from private_reviewed_existing_history.report_targets(t.slug)) and not exists(select 1 from private_historical_statistics.markers mk where mk.competition_id=t.cid and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)rt where rt.source_match_id=mk.source_match_id)),'exact installed reviewed marker set required');
 perform private_reviewed_existing_history.opening(t.slug,clock_timestamp());
 state:=private_reviewed_existing_history.state_sha(t.slug);attempt:=jsonb_build_object('slug',t.slug,'mainCommit',p_main_sha,'policySha256',t.policy_sha,'cleanupBeforeSha256',r.before_sha,'footballStateSha256',state,'claimedAt',clock_timestamp());
 insert into private_reviewed_existing_history.price_attempts(slug,main_sha,policy_sha,cleanup_before_sha,football_state_sha)values(t.slug,p_main_sha,t.policy_sha,r.before_sha,state);
 return attempt;
end$$;

create function public.record_reviewed_existing_prices(p_slug text,p_main_sha text,p_policy_sha text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;r private_reviewed_existing_history.cleanup_receipts%rowtype;a private_reviewed_existing_history.price_attempts%rowtype;state text;prices text;receipt jsonb;begin
 select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 perform private_reviewed_existing_history.require(current_setting('transaction_isolation')='read committed' and p_main_sha~'^[a-f0-9]{40}$' and p_policy_sha=t.policy_sha,'READ COMMITTED and exact source policy/main required');
 select * into r from private_reviewed_existing_history.cleanup_receipts where slug=t.slug for update;
 perform private_reviewed_existing_history.require(r.slug=t.slug and r.main_sha=p_main_sha and r.policy_sha=t.policy_sha and r.after_sha=private_reviewed_existing_history.state_sha(t.slug),'cleanup receipt and post-cleanup football state must match');
 select * into a from private_reviewed_existing_history.price_attempts where slug=t.slug for update;
 perform private_reviewed_existing_history.require(a.slug=t.slug and a.main_sha=p_main_sha and a.policy_sha=t.policy_sha and a.cleanup_before_sha=r.before_sha and a.football_state_sha=private_reviewed_existing_history.state_sha(t.slug),'one-use pricing claim and exact post-cleanup state required');
 perform private_reviewed_existing_history.require(not exists(select 1 from private_reviewed_existing_history.price_receipts where slug=t.slug),'price receipt already exists; never retry ambiguous price write');
 state:=private_reviewed_existing_history.state_sha(t.slug);prices:=private_reviewed_existing_history.price_sha(t.slug);
 receipt:=jsonb_build_object('slug',t.slug,'mainCommit',p_main_sha,'policySha256',t.policy_sha,'cleanupBeforeSha256',r.before_sha,'footballStateSha256',state,'priceSha256',prices,'recordedAt',clock_timestamp());
 insert into private_reviewed_existing_history.price_receipts(slug,main_sha,policy_sha,cleanup_before_sha,football_state_sha,price_vector_sha)values(t.slug,p_main_sha,t.policy_sha,r.before_sha,state,prices);
 return receipt;
end$$;

create function private_reviewed_existing_history.release_core(p_slug text,p_main_sha text,p_policy_sha text,p_expected_preview_sha text,p_activate boolean,p_clock timestamptz) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare t record;c competitions%rowtype;p private_historical_statistics.policies%rowtype;cleanup private_reviewed_existing_history.cleanup_receipts%rowtype;attempt private_reviewed_existing_history.price_attempts%rowtype;prices private_reviewed_existing_history.price_receipts%rowtype;marker jsonb;opening jsonb;st jsonb;cost numeric;state text;vector text;preview text;result jsonb;
begin
 select * into t from private_reviewed_existing_history.target(p_slug);perform private_reviewed_existing_history.require(t.cid is not null,'unknown slug');
 perform private_reviewed_existing_history.require(current_setting('transaction_isolation')='read committed' and p_main_sha~'^[a-f0-9]{40}$' and p_policy_sha=t.policy_sha,'READ COMMITTED and exact main/policy SHA required');
 perform private_reviewed_existing_history.require((not p_activate and p_expected_preview_sha is null) or (p_activate and p_expected_preview_sha~'^[a-f0-9]{64}$'),'activation requires the exact-format reviewed preview SHA');
 lock table countries,competitions,rounds,teams,players,matches,appearances,goals,fantasy_teams,fantasy_roster,fantasy_lineups,fantasy_transfers,fantasy_chips,position_votes,position_votes_deleted,assist_votes,assist_votes_deleted,player_scores,statistika_igralcev,tocke_krogov,uradne_odsotnosti,profil_igralca_plus in share row exclusive mode;
 lock table private_historical_statistics.policies,private_historical_statistics.installed_policies,private_historical_statistics.markers,private_historical_statistics.source_club_bindings,private_reviewed_existing_history.cleanup_receipts,private_reviewed_existing_history.price_receipts in share row exclusive mode;
 select * into c from competitions where id=t.cid for update;select * into p from private_historical_statistics.policies where id=t.policy_id;
 perform private_reviewed_existing_history.require(c.slug=t.slug and c.source=t.provider and c.source_league_code=t.code and c.source_policy='reviewed-existing-history-20261023-v1' and not c.sezona_koledarska and not c.active and exists(select 1 from countries where id=c.country_id and code=case t.provider when 'isthmian' then 'GB' when 'hlf' then 'RO' when 'nfsbih' then 'BA' end) and p.policy_sha256=t.policy_sha and p.document->>'competitionSlug'=t.slug and p.document->>'provider'=t.provider,'exact inactive native country/source/code/policy binding required');
 perform private_reviewed_existing_history.require(not exists(select 1 from fantasy_teams where competition_id=t.cid) and not exists(select 1 from fantasy_roster fr join players pp on pp.id=fr.player_id where pp.competition_id=t.cid) and not exists(select 1 from fantasy_lineups l join rounds rr on rr.id=l.round_id where rr.competition_id=t.cid) and not exists(select 1 from fantasy_transfers ft join rounds rr on rr.id=ft.round_id where rr.competition_id=t.cid) and not exists(select 1 from fantasy_chips fc join rounds rr on rr.id=fc.round_id where rr.competition_id=t.cid) and not exists(select 1 from position_votes v join players pp on pp.id=v.player_id where pp.competition_id=t.cid) and not exists(select 1 from position_votes_deleted v join players pp on pp.id=v.player_id where pp.competition_id=t.cid) and not exists(select 1 from assist_votes av join goals g on g.id=av.goal_id join matches mm on mm.id=g.match_id join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid) and not exists(select 1 from assist_votes_deleted av join goals g on g.id=av.goal_id join matches mm on mm.id=g.match_id join rounds rr on rr.id=mm.round_id where rr.competition_id=t.cid),'no post-cleanup user activity required at activation');
 select * into cleanup from private_reviewed_existing_history.cleanup_receipts where slug=t.slug;
 select * into attempt from private_reviewed_existing_history.price_attempts where slug=t.slug;
 select * into prices from private_reviewed_existing_history.price_receipts where slug=t.slug;
 state:=private_reviewed_existing_history.state_sha(t.slug);vector:=private_reviewed_existing_history.price_sha(t.slug);
 perform private_reviewed_existing_history.require(cleanup.main_sha=p_main_sha and cleanup.policy_sha=t.policy_sha and cleanup.after_sha=state,'cleanup receipt/current football state mismatch');
 perform private_reviewed_existing_history.require(attempt.main_sha=p_main_sha and attempt.policy_sha=t.policy_sha and attempt.cleanup_before_sha=cleanup.before_sha and attempt.football_state_sha=state,'one-use pre-price claim/current football state mismatch');
 perform private_reviewed_existing_history.require(prices.main_sha=p_main_sha and prices.policy_sha=t.policy_sha and prices.cleanup_before_sha=cleanup.before_sha and prices.football_state_sha=state and prices.price_vector_sha=vector,'fresh price receipt/current full price vector mismatch');
 marker:=public.get_installed_historical_statistics_markers(t.cid);
 perform private_reviewed_existing_history.require(marker->>'policyId'=t.policy_id and marker->>'policySha256'=t.policy_sha and jsonb_array_length(marker->'markers')=(select count(*) from private_reviewed_existing_history.report_targets(t.slug)) and not exists(select 1 from private_historical_statistics.markers mk where mk.competition_id=t.cid and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)rt join jsonb_array_elements(marker->'markers') as j(value) on j.value->>'sourceMatchId'=rt.source_match_id where rt.source_match_id=mk.source_match_id)),'exactly the one approved unavailable marker required');
 opening:=private_reviewed_existing_history.opening(t.slug,p_clock);
 perform private_reviewed_existing_history.require(c.prvi_fantasy_krog=(opening->>'round')::int,'first future round changed after cleanup');
 perform private_reviewed_existing_history.require((select count(*) from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and r.season='2026/27' and m.imported_at is not null and m.statistics_status='available')=t.current_reports-(select count(*) from private_reviewed_existing_history.report_targets(t.slug)rt where rt.season='2026/27') and (select count(*) from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and r.season='2026/27' and m.statistics_status='unavailable_historical')=(select count(*) from private_reviewed_existing_history.report_targets(t.slug)rt where rt.season='2026/27') and (t.cid<>979 or (select count(*) from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and r.season='2025/26' and m.imported_at is not null and m.statistics_status='available')=t.archive_reports-(select count(*) from private_reviewed_existing_history.report_targets(t.slug)rt where rt.season='2025/26')),'exact per-season report inventory plus approved markers required');
 perform private_reviewed_existing_history.require(not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and ((m.statistics_status='unavailable_historical' and not exists(select 1 from private_reviewed_existing_history.report_targets(t.slug)rt where rt.mid=m.id)) or (coalesce(m.played_on,r.played_on)<(p_clock at time zone 'Europe/Ljubljana')::date and not m.kontumacija and m.vir_brez_izida is not true and m.statistics_status<>'unavailable_historical' and (m.imported_at is null or m.statistics_status<>'available')) or (m.imported_at is not null and (m.home_goals is null or m.away_goals is null or m.zapisnik_id is null or m.statistics_status<>'available')))),'no past missing or extra unavailable reports');
 perform private_reviewed_existing_history.require(not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and r.season='2026/27' and m.imported_at is not null and m.zapisnik_id not like case t.provider when 'isthmian' then 'gb%' when 'hlf' then '%-%-%-%-%' when 'nfsbih' then 'ba%' end),'foreign current report namespace');
 perform private_reviewed_existing_history.require(not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and m.imported_at is not null and (m.home_goals is distinct from(select count(*)::int from goals g where g.match_id=m.id and ((g.team_id=m.home_team_id and not g.is_own_goal) or (g.team_id=m.away_team_id and g.is_own_goal))) or m.away_goals is distinct from(select count(*)::int from goals g where g.match_id=m.id and ((g.team_id=m.away_team_id and not g.is_own_goal) or (g.team_id=m.home_team_id and g.is_own_goal))))),'all official score totals must reconcile with ordinary and own goals');
 perform private_reviewed_existing_history.require(not exists(select 1 from goals g join matches m on m.id=g.match_id join rounds r on r.id=m.round_id where r.competition_id=t.cid and m.imported_at is not null and (g.team_id not in(m.home_team_id,m.away_team_id) or g.minute is null or g.minute<0 or g.minute>130 or not exists(select 1 from appearances a where a.match_id=m.id and a.player_id=g.scorer_id and a.team_id=g.team_id))) and not exists(select 1 from appearances a join players pl on pl.id=a.player_id join matches m on m.id=a.match_id join rounds r on r.id=m.round_id where r.competition_id=t.cid and m.imported_at is not null and (pl.competition_id<>t.cid or a.team_id not in(m.home_team_id,m.away_team_id) or a.minutes_played is null or a.minute_on is null or a.minute_off is null or a.minute_on<0 or a.minute_off>130 or a.minute_on>a.minute_off or a.minutes_played<>a.minute_off-a.minute_on or a.started and a.minute_on<>0)),'player/goal identity and feasible red-card/stoppage-time minutes required');
 perform private_reviewed_existing_history.require(not exists(select 1 from matches m join rounds r on r.id=m.round_id where r.competition_id=t.cid and m.imported_at is not null and (exists(select 1 from(values(m.home_team_id),(m.away_team_id))s(id) where (select count(*) from appearances a where a.match_id=m.id and a.team_id=s.id and a.started) not between 7 and 11 or (select count(*) from appearances a where a.match_id=m.id and a.team_id=s.id and a.started and a.is_goalkeeper)<>1))), 'every imported team has legal starters and exactly one explicit starting goalkeeper');
 perform private_reviewed_existing_history.require(not exists(with sides as(select m.id,m.home_team_id team_id from matches m join rounds rr on rr.id=m.round_id where rr.competition_id=t.cid and m.imported_at is not null union all select m.id,m.away_team_id from matches m join rounds rr on rr.id=m.round_id where rr.competition_id=t.cid and m.imported_at is not null), totals as(select s.id,s.team_id,count(*) filter(where a.started)::int starters,sum(a.minutes_played)::int played_minutes,sum(case when a.red_cards>0 and (a.started or a.minutes_played>0) then greatest(0,90-a.minute_off) else 0 end)::int red_loss from sides s join appearances a on a.match_id=s.id and a.team_id=s.team_id group by s.id,s.team_id) select 1 from totals where played_minutes<>starters*90-red_loss),'team player minutes must reconcile with lineup and on-field dismissals');
 perform private_reviewed_existing_history.require(not exists(select 1 from public.zliti_igralci(c.slug,t.provider)where preskok is null),'unresolved player-identity collisions');
 st:=public.stanje_lige(t.cid);cost:=public.najcenejsi_kader(st->'igralci');
 perform private_reviewed_existing_history.require(cost is not null and cost<=100 and (st->>'najvisja_cena')::numeric>=6 and coalesce((st->>'privzetih')::numeric/nullif((st->>'aktivnih')::numeric,0),1)<=0.8 and (st->>'golov_brez_nastopa')::int=0 and not exists(select 1 from teams tm where tm.country_id=c.country_id and exists(select 1 from players pl where pl.competition_id=t.cid and pl.team_id=tm.id and pl.active) and not exists(select 1 from players pl where pl.competition_id=t.cid and pl.team_id=tm.id and pl.active and pl.position='GK' and pl.position_source in('zapisnik','admin','klub'))),'fresh prices: legal15 <=100, varied prices, no off-field scorer and trusted active goalkeeper per club required');
 state:=private_reviewed_existing_history.state_sha(t.slug);vector:=private_reviewed_existing_history.price_sha(t.slug);
 preview:=encode(sha256(convert_to(jsonb_build_object('slug',t.slug,'competitionId',t.cid,'mainCommit',p_main_sha,'policyId',t.policy_id,'policySha256',t.policy_sha,'footballStateSha256',state,'priceSha256',vector,'opening',opening,'firstRound',(opening->>'round')::int,'firstDeadline',opening->'deadline')::text,'UTF8')),'hex');
 perform private_reviewed_existing_history.require((not p_activate and p_expected_preview_sha is null) or (p_expected_preview_sha~'^[a-f0-9]{64}$' and p_expected_preview_sha=preview),'expected preview SHA required for activation and must match the exact preview');
 result:=jsonb_build_object('ready',true,'active',false,'reason',null,'slug',t.slug,'competitionId',t.cid,'mainCommit',p_main_sha,'policyId',t.policy_id,'policySha256',t.policy_sha,'markers',marker,'firstRound',(opening->>'round')::int,'firstDeadline',opening->'deadline','firstPlayedOn',opening->'firstPlayedOn','cheapestLegal15',cost,'priceSha256',vector,'previewSha256',preview);
 if p_activate then
  perform private_historical_statistics.authorize_release(t.cid,t.policy_id,t.policy_sha,preview);
  update competitions set active=true where id=t.cid and not active;perform private_reviewed_existing_history.require(found,'competition was not inactive during guarded activation');
  result:=result||jsonb_build_object('active',true);
 end if;
 return result;
end$$;

create function public.check_reviewed_existing_release(p_slug text,p_main_sha text,p_policy_sha text,p_expected_preview_sha text default null,p_activate boolean default false) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin
 return private_reviewed_existing_history.release_core(p_slug,p_main_sha,p_policy_sha,p_expected_preview_sha,p_activate,clock_timestamp());
 exception when others then if p_activate then raise;end if;return jsonb_build_object('ready',false,'active',false,'reason',sqlerrm,'slug',p_slug,'previewSha256',null);end$$;

create function private_reviewed_existing_history.protect() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin raise exception 'REVIEWED_EXISTING: immutable receipt';end$$;
create function private_reviewed_existing_history.protect_catalog() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare oldj jsonb;newj jsonb;allowed bigint;begin oldj:=to_jsonb(old);if tg_op='UPDATE' then newj:=to_jsonb(new);end if;
 if tg_table_name='policies' and oldj->>'id' in('gb-npl-midlands-historical-unavailable-2026-10-23-v1','gb-sfl-d1-south-historical-unavailable-2026-10-23-v1','ro-liga3-s1-historical-unavailable-2026-10-23-v1','ba-wwin-liga-bih-historical-unavailable-2026-10-23-v1') then raise exception 'REVIEWED_EXISTING: immutable approved policy';
 elsif tg_table_name='source_club_bindings' and oldj->>'provider' in('isthmian','hlf','nfsbih') and oldj->>'source_club_id' in('68072a04bda6e04641c6e014','6a0adf9eda5d0d0847a023fc','6a0adf9eda5d0d0847a02391','6a0adf9eda5d0d0847a02385','a91ef983-185f-4a35-b5cc-6421c820bd97','3e8d6813-1504-43b1-beef-4118d343f2c7','6853aad421dd3fcf18f4fa48','68072882bda6e04641c6e003','831','409','517') then
  allowed:=case oldj->>'source_club_id' when '68072a04bda6e04641c6e014' then 10869 when '6a0adf9eda5d0d0847a023fc' then 10864 when '6a0adf9eda5d0d0847a02391' then 10535 when '6a0adf9eda5d0d0847a02385' then 10517 when 'a91ef983-185f-4a35-b5cc-6421c820bd97' then 3016 when '3e8d6813-1504-43b1-beef-4118d343f2c7' then 3017 when '6853aad421dd3fcf18f4fa48' then 10862 when '68072882bda6e04641c6e003' then 10847 when '831' then 10876 when '409' then 10872 when '517' then 10874 end;
  if tg_op='UPDATE' and oldj->'bound_team_id'='null'::jsonb and (newj-'bound_team_id')=(oldj-'bound_team_id') and (newj->>'bound_team_id')::bigint=allowed then return new;end if;
  raise exception 'REVIEWED_EXISTING: immutable reviewed source-club binding';
 end if;
 if tg_op='DELETE' then return old;else return new;end if;
end$$;
